// Organic O — Framer code component
// BUILD: SCALE-DPR-02 · commit dda6331 · sha ba3ccaaae8ab
// A WebGL "O" as a background whose shape, material AND camera angle morph
// from preset A -> preset B as the visitor scrolls between two sections.
//
//   - Self-contained: the whole shader is embedded (base64) in this file, so
//     there is nothing to host and no external URL to break.
//   - Renders at 1x by default and PAUSES when scrolled offscreen, so it stays
//     light even with several breakpoints on the Framer canvas.
//   - Non-interactive by default; flip "Interactive" on to let visitors orbit.
//
// SET YOUR LOOKS: paste your t1 into "Preset A JSON" and t2 into "Preset B
// JSON" (these win over the name fields). Built-in names also work:
// "trial 6", "transparent", "reference", "lava", "ghost".

import { useRef, useEffect, useCallback } from "react"
import { addPropertyControls, ControlType } from "framer"
import { useScroll, useMotionValueEvent } from "framer-motion"

const PAGE_B64 = ""
/* atob yields one char per BYTE, so UTF-8 text (em dashes, middots, the
   preset labels) arrives mojibaked unless it is decoded as UTF-8. */
const RAW =
    typeof atob !== "undefined"
        ? new TextDecoder("utf-8").decode(
              Uint8Array.from(atob(PAGE_B64), (c) => c.charCodeAt(0))
          )
        : ""
// srcDoc has no URL to carry ?embed=1, so switch on background mode via a flag
const PAGE_HTML = RAW.replace("<head>", "<head><script>window.__ORGANIC_EMBED__=true;<\/script>")
const PAGE_HTML_T = RAW.replace("<head>", "<head><script>window.__ORGANIC_EMBED__=true;window.__ORGANIC_TRANSPARENT__=true;<\/script>")
const BUILD = { id: "SCALE-DPR-02", commit: "dda6331", sha: "ba3ccaaae8ab" }
const TSX_BUILD = "FIX-02"
console.log("Organic O TSX BUILD " + TSX_BUILD, BUILD)

// Your dialed-in looks, baked in as the default A -> B journey:
//   t1: zoomed-in, frosted, inky, front-facing
//   t2: zoomed-out, transparent, ink drained, rotated ~146deg
const BUILT_IN = {
    t1: {"dials": {"debug": 0, "iso": 0, "ink": 0.95, "gravity": 0.82, "crange": 0.6, "light": 0.9, "glare": 0.85, "speed": 3.65, "fluid": 0.74, "fcenter": 0.19, "fthick": 0.47, "fdepth": 0.235, "flag": 0.35, "fsmooth": 0.72, "spin": 0.16, "tilt": 0.45, "tiltspd": 1, "wob": 0.45, "wobspd": 0.5, "morph": 0.79, "morphspd": 1.89, "ring": 0.71, "lobe": 0.17, "stretch": 0.14, "tube": 0.175, "flat": 0.7, "taper": 0.28, "zoom": 3.49, "frost": 0.18, "wall": 0.2, "speckle": 0, "soft": 0.9, "grain": 0, "bg": 0.955, "optv1": 1, "refrfull": 1, "exposure": 1.15, "rolloff": 0.85, "lift": 0.015, "shellth": 0.16, "shellcl": 0.7, "coresoft": 0.18, "fresstr": 1, "fresf0": 0.04, "reflstr": 1, "studiorot": 0.5, "stripw": 0.22, "strips": 0.16, "curvresp": 0.6, "hiwidth": 0.09, "hiint": 1, "ior": 1.45, "refrstr": 0.7, "disp": 0.012}, "view": {"yaw": 0, "pitch": 0}, "blobs": [{"color": "#101c33", "size": 0.55, "speed": 0.32, "amt": 1, "tail": 0.6, "drift": 0.45, "follow": false}, {"color": "#386bbc", "size": 0.85, "speed": -0.15, "amt": 0.4, "tail": 0.5, "drift": 0.7, "follow": false}]},
    t2: {"dials": {"debug": 0, "iso": 0, "ink": 0.95, "gravity": 0.82, "crange": 0.6, "light": 0.9, "glare": 0.85, "speed": 3.65, "fluid": 0.74, "fcenter": 0.19, "fthick": 0.47, "fdepth": 0.235, "flag": 0.35, "fsmooth": 0.72, "spin": 0.16, "tilt": 0.45, "tiltspd": 1, "wob": 0.64, "wobspd": 0.65, "morph": 0.84, "morphspd": 0.4, "ring": 0.71, "lobe": 0.17, "stretch": 0.14, "tube": 0.175, "flat": 0.7, "taper": 0.19, "zoom": 0.5, "frost": 0, "wall": 0.2, "speckle": 0, "soft": 0.9, "grain": 0, "bg": 0.955, "optv1": 1, "refrfull": 1, "exposure": 1.15, "rolloff": 0.85, "lift": 0.015, "shellth": 0.16, "shellcl": 0.7, "coresoft": 0.18, "fresstr": 1, "fresf0": 0.04, "reflstr": 1, "studiorot": 0.5, "stripw": 0.22, "strips": 0.16, "curvresp": 0.6, "hiwidth": 0.09, "hiint": 1, "ior": 1.45, "refrstr": 0.7, "disp": 0.012}, "view": {"yaw": 2.54591796875, "pitch": 0.0007421874999999742}, "blobs": [{"color": "#101c33", "size": 0.15, "speed": 0.35, "amt": 0, "tail": 0.6, "drift": 0.45, "follow": false}, {"color": "#386bbc", "size": 0.15, "speed": -0.15, "amt": 0, "tail": 0.5, "drift": 0.7, "follow": false}]},
}

const clamp = (v, a, b) => Math.max(a, Math.min(b, v))
function parseJSON(s) {
    if (!s) return null
    try {
        const o = JSON.parse(s)
        return o && o.dials && o.blobs ? o : null
    } catch {
        return null
    }
}

export default function OrganicO(props) {
    /* Default parameters, not defaultProps: React 18.3 warns on defaultProps
       for function components and React 19 drops it. Framer reads the
       property-control defaults for the panel; these keep the component
       correct when it is rendered without a panel (previews, tests). */
    const {
        presetAName = "t1", presetBName = "t2",
        presetAJson = "", presetBJson = "",
        interactive = false, scrollStart = 0, scrollEnd = 1, quality = 0,
        transparentBg = true, shadowKill = false, alphaDebug = false,
        buildBadge = true, zoomMul = 1, style,
    } = props

    const ref = useRef(null)
    const { scrollYProgress } = useScroll()

    const A = parseJSON(presetAJson) || BUILT_IN[presetAName] || presetAName
    const B = parseJSON(presetBJson) || BUILT_IN[presetBName] || presetBName

    const post = useCallback((msg) => {
        ref.current?.contentWindow?.postMessage({ type: "organicO", ...msg }, "*")
    }, [])

    /* srcDoc is fixed for the component's lifetime. Deriving it from a live
       prop would swap the document on every toggle, tearing down the WebGL
       context and recompiling the shader; transparency changes travel by
       postMessage instead, so exactly ONE context and ONE RAF loop exist
       from mount to unmount. */
    const initialSrcDoc = useRef(transparentBg ? PAGE_HTML_T : PAGE_HTML)

    const sendConfig = useCallback(() => {
        post({ a: A, b: B, interactive, dpr: quality, transparent: transparentBg,
               shadowKill, alphaDebug, badge: buildBadge, zoomMul })
    }, [post, JSON.stringify(A), JSON.stringify(B), interactive, quality, transparentBg,
        shadowKill, alphaDebug, buildBadge, zoomMul])

    useEffect(() => { sendConfig() }, [sendConfig])
    useEffect(() => { console.log("Organic O TSX BUILD " + TSX_BUILD + " mounted", BUILD) }, [])

    // coalesce progress to at most one message per animation frame
    const pending = useRef(null)
    const raf = useRef(0)
    useMotionValueEvent(scrollYProgress, "change", (v) => {
        pending.current = clamp(
            (v - scrollStart) / Math.max(1e-6, scrollEnd - scrollStart), 0, 1
        )
        if (!raf.current) {
            raf.current = requestAnimationFrame(() => {
                raf.current = 0
                if (pending.current != null) post({ progress: pending.current })
            })
        }
    })
    // cancel the pending frame on unmount so no callback fires into a dead iframe
    useEffect(() => () => { if (raf.current) cancelAnimationFrame(raf.current) }, [])

    // pause GPU work while the O is out of view (and on inactive breakpoints)
    useEffect(() => {
        const el = ref.current
        if (!el || typeof IntersectionObserver === "undefined") return
        const io = new IntersectionObserver(
            ([e]) => post({ paused: !e.isIntersecting }),
            { rootMargin: "120px" }
        )
        io.observe(el)
        return () => io.disconnect()
    }, [post])

    /* SHADOW KILL also overrides anything Framer injected through `style`
       (layer effects land there as boxShadow / filter: drop-shadow). With it
       on, no shadow can reach the page from the React layer either. */
    const killCss = shadowKill
        ? { boxShadow: "none", filter: "none", WebkitFilter: "none", backdropFilter: "none" }
        : null

    return (
        <div style={{ position: "relative", width: "100%", height: "100%", ...style, ...killCss }}>
            <iframe
                ref={ref}
                srcDoc={initialSrcDoc.current}
                allowtransparency="true"
                onLoad={sendConfig}
                title="Organic O"
                style={{
                    width: "100%",
                    height: "100%",
                    border: "none",
                    background: "transparent",
                    colorScheme: "normal",
                    display: "block",
                    pointerEvents: interactive ? "auto" : "none",
                    ...killCss,
                }}
            />
            {buildBadge && (
                <div
                    style={{
                        position: "absolute", left: 8, top: 8, zIndex: 2147483647,
                        pointerEvents: "none", background: "#b4004e", color: "#fff",
                        font: "11px/1.45 ui-monospace, SFMono-Regular, Menlo, monospace",
                        padding: "4px 8px", borderRadius: 3, whiteSpace: "pre",
                        boxShadow: "none",
                    }}
                >
                    {"TSX BUILD: " + TSX_BUILD + " · page " + BUILD.id + " · " + BUILD.sha}
                </div>
            )}
        </div>
    )
}

addPropertyControls(OrganicO, {
    presetAName: { type: ControlType.String, title: "Preset A", placeholder: "t1 (built-in)" },
    presetBName: { type: ControlType.String, title: "Preset B", placeholder: "t2 (built-in)" },
    presetAJson: { type: ControlType.String, title: "Preset A JSON", displayTextArea: true, placeholder: "(optional) paste t1 JSON" },
    presetBJson: { type: ControlType.String, title: "Preset B JSON", displayTextArea: true, placeholder: "(optional) paste t2 JSON" },
    interactive: { type: ControlType.Boolean, title: "Interactive", defaultValue: false, enabledTitle: "On", disabledTitle: "Off" },
    scrollStart: { type: ControlType.Number, title: "Scroll start", min: 0, max: 1, step: 0.01, defaultValue: 0 },
    scrollEnd: { type: ControlType.Number, title: "Scroll end", min: 0, max: 1, step: 0.01, defaultValue: 1 },
    quality: { type: ControlType.Number, title: "Quality (DPR)", min: 0, max: 2, step: 0.25, defaultValue: 0, description: "0 = match the screen (sharpest; fixes rim hairlines on retina). 1 = half-res, fastest." },
    zoomMul: { type: ControlType.Number, title: "Scale", min: 0.2, max: 5, step: 0.05, defaultValue: 1, description: "Multiplies the preset zoom. Apparent size follows the container HEIGHT." },
    transparentBg: { type: ControlType.Boolean, title: "Transparent BG", defaultValue: true, enabledTitle: "On", disabledTitle: "Off", description: "Off = the shader paints its own studio backdrop." },
    shadowKill: { type: ControlType.Boolean, title: "SHADOW KILL", defaultValue: false, enabledTitle: "On", disabledTitle: "Off", description: "Diagnostic: zero every shader-side and CSS-side shadow inside the iframe." },
    alphaDebug: { type: ControlType.Boolean, title: "Alpha debug", defaultValue: false, enabledTitle: "On", disabledTitle: "Off", description: "Diagnostic: black = alpha 0, white = alpha 1." },
    buildBadge: { type: ControlType.Boolean, title: "Build badge", defaultValue: true, enabledTitle: "Show", disabledTitle: "Hide", description: "Shows BUILD id / commit / sha in the corner. Turn off before publishing." },
})
